-- Rotas do sitemap público. Cada linha aponta para um contrato que já existe. O corpo antigo não entra.

create table if not exists site_route (
  path text primary key,
  locale text not null,
  kind text not null,
  title text not null,
  lead text not null,
  status text not null default 'sugestao' check (status = 'sugestao')
);

on conflict (path) do nothing;
